import gurobipy as gp
from gurobipy import GRB
shelves = []
shelf_caps = {}
products = []
item_value = {}
item_weight = {}
for rec in LEGACY_RECORDS:
    v = rec['values']
    if 'resource_id' in v and 'resource_capacity' in v:
        rid = str(v['resource_id'])
        shelves.append(rid)
        shelf_caps[rid] = int(v['resource_capacity'])
    if 'item_name' in v and 'item_value' in v and ('resource_requirement' in v):
        pname = str(v['item_name'])
        products.append(pname)
        item_value[pname] = int(v['item_value'])
        item_weight[pname] = int(v['resource_requirement'])
if len(shelves) == 0 or len(products) == 0:
    raise ValueError('No shelves or products found in LEGACY_RECORDS')
for rid in shelves:
    if rid not in shelf_caps:
        raise ValueError(f'Missing capacity for shelf {rid}')
for pname in products:
    if pname not in item_value or pname not in item_weight:
        raise ValueError(f'Missing value or weight for product {pname}')
m = gp.Model('BigMart_Shelf_Allocation')
x = m.addVars(shelves, products, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((item_value[p] * x[s, p] for s in shelves for p in products)), GRB.MAXIMIZE)
m.addConstrs((gp.quicksum((item_weight[p] * x[s, p] for p in products)) <= shelf_caps[s] for s in shelves), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')